/*
 * A191122  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-1 and 4x are in a.
 * https://oeis.org/A191122
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 17, u16 n <= 713, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A191122: Increasing sequence generated by
 *  a(1)=1; if x is in a then 3x-1 and 4x are in a.
 *  The sequence is produced by a breadth‑first expansion
 *  of the set of reachable numbers, sorted in increasing order.
 *  The function a(n) returns the n‑th term (1‑based).          */
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* ---- minimal heap for seq_t --------------------------------- */
static seq_t *heap = NULL;
static size_t heap_size = 0, heap_cap = 0;

static void heap_resize(void) {
    size_t new_cap = heap_cap ? heap_cap << 1 : 64;
    seq_t *new_hp = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
    if (!new_hp) abort();
    heap = new_hp;
    heap_cap = new_cap;
}

static void heap_push(seq_t v) {
    if (heap_size == heap_cap) heap_resize();
    size_t i = heap_size++;
    heap[i] = v;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        seq_t tmp = heap[p]; heap[p] = heap[i]; heap[i] = tmp;
        i = p;
    }
}

static seq_t heap_pop(void) {
    seq_t ret = heap[0];
    heap[0] = heap[--heap_size];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1, r = l + 1, smallest = i;
        if (l < heap_size && heap[l] < heap[smallest]) smallest = l;
        if (r < heap_size && heap[r] < heap[smallest]) smallest = r;
        if (smallest == i) break;
        seq_t tmp = heap[i]; heap[i] = heap[smallest]; heap[smallest] = tmp;
        i = smallest;
    }
    return ret;
}

/* ---- hash set for seq_t (linear probing) --------------------- */
static seq_t *hash_keys = NULL;
static size_t hash_cap = 0, hash_mask = 0;

static void hash_init(void) {
    hash_cap = 1 << 17;          /* 131072 entries, load < 1/4 for n≈10^4 */
    hash_mask = hash_cap - 1;
    hash_keys = (seq_t *)calloc(hash_cap, sizeof(seq_t));
    if (!hash_keys) abort();
}

static inline uint64_t hash_seq(seq_t v) {
    uint64_t x = (uint64_t)v;
    /* 64‑bit multiplicative hash */
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static bool hash_insert(seq_t v) {
    if (!hash_keys) hash_init();
    size_t h = hash_seq(v) & hash_mask;
    for (;;) {
        seq_t cur = hash_keys[h];
        if (cur == 0) {               /* empty slot */
            hash_keys[h] = v;
            return true;              /* inserted */
        }
        if (cur == v) return false;   /* already present */
        h = (h + 1) & hash_mask;      /* probe */
    }
}

/* ---- cache for generated sequence ---------------------------- */
static seq_t *cache = NULL;
static size_t cache_len = 0, cache_cap = 0;

static void cache_resize(size_t min_cap) {
    if (cache_cap >= min_cap) return;
    size_t new_cap = cache_cap ? cache_cap << 1 : 64;
    if (new_cap < min_cap) new_cap = min_cap;
    seq_t *new_cp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cp) abort();
    cache = new_cp;
    cache_cap = new_cap;
}

static void ensure_cache(idx_t n) {
    if (cache_len >= n) return;
    /* Initialise first element if not already done */
    if (cache_len == 0 && heap_size == 0) {
        if (hash_insert((seq_t)1)) heap_push((seq_t)1);
    }
    while (cache_len < n) {
        seq_t x = heap_pop();
        cache_resize(cache_len + 1);
        cache[cache_len++] = x;
        seq_t child1 = (seq_t)3 * x - (seq_t)1;
        seq_t child2 = (seq_t)4 * x;
        if (hash_insert(child1)) heap_push(child1);
        if (hash_insert(child2)) heap_push(child2);
    }
}

/* ---- the requested function --------------------------------- */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;     /* undefined for n=0, return 0 */
    ensure_cache(n);
    return cache[n - 1];
}
